    "factor_updates": [
      {
        "factor": "Empirical evidence of state-actor chemical agent use or presence in Ukraine (e.g., CS, chloropicrin) as documented by OPCW and allied intelligence",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "OPCW and intelligence reports since 2024–2025 document detections of riot-control agents in Ukraine, signaling state deployment and elevating near-term risk."
      },
      {
        "factor": "Credible intelligence warnings that Russia is expanding chemical weapons use",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Dutch/German intelligence warnings and European assessments in 2025–2026 warn of increasing use of chemical agents by Russia, pushing escalation risk and likelihood of CW use higher."
      },
      {
        "factor": "Chemical Weapons Convention norms and OPCW monitoring effects",
        "direction": "down",
        "magnitude": "strong",
        "rationale": "CWC norms deter CW use; ongoing investigations and attribution challenges notwithstanding, normative constraints pull probability downward."
      },
      {
        "factor": "Attribution uncertainty for incidents involving CS/chloropicrin",
        "direction": "neutral",
        "magnitude": "weak",
        "rationale": "Ambiguity about responsibility dampens precision in forecasting but does not eliminate risk, leaving the net effect largely neutral on near-term probability."
      },
      {
        "factor": "Time horizon and conflict dynamics in Ukraine (risk of escalation)",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "As the war persists toward 2026 and episodic chemical incidents continue to appear, escalation dynamics that favor CW use would raise the probability above the anchor."
      }
    ],
    "synthesis_rationale": "Starting from a low anchor (12%), the factors were applied cumulatively with explicit directions and magnitudes. Upward factors raise the posterior toward a moderate level; the down factor from norms prevents inflation beyond reasonable bounds, and attribution uncertainty introduces residual variance. The resulting calibrated estimate is 0.58 with a range reflecting calibration."
  }
}

